    if (polyLons[0] != polyLons[polyLons.length - 1]) {
      throw new IllegalArgumentException(
          "first and last points of the polygon must be the same (it must close itself): polyLons[0]="
              + polyLons[0]
              + " polyLons["
              + (polyLons.length - 1)
              + "]="
              + polyLons[polyLons.length - 1]);
    }
