import math
BITS=32
LAT_SCALE=(1<<BITS)/180.0
LAT_DECODE=1/LAT_SCALE
LON_SCALE=(1<<BITS)/360.0
LON_DECODE=1/LON_SCALE
base=2**31-1
def dec_lat(e): return e*LAT_DECODE
def dec_lon(e): return e*LON_DECODE
def enc_lat(lat):
    if lat==90.0: lat=math.nextafter(lat,-math.inf)
    return math.floor(lat/LAT_DECODE)
def enc_lat_ceil(lat):
    if lat==90.0: lat=math.nextafter(lat,-math.inf)
    return math.ceil(lat/LAT_DECODE)
def enc_lon(lon):
    if lon==180.0: lon=math.nextafter(lon,-math.inf)
    return math.floor(lon/LON_DECODE)
def enc_lon_ceil(lon):
    if lon==180.0: lon=math.nextafter(lon,-math.inf)
    return math.ceil(lon/LON_DECODE)
print('LAT_DECODE',LAT_DECODE,'LON_DECODE',LON_DECODE)
for d in range(-5,2):
    e=base+d
    print(d,e,'lat',repr(dec_lat(e)),'lon',repr(dec_lon(e)),'enc_lat',enc_lat(dec_lat(e)),'enc_lat_ceil',enc_lat_ceil(dec_lat(e)),'enc_lon',enc_lon(dec_lon(e)),'enc_lon_ceil',enc_lon_ceil(dec_lon(e)))
minLat=dec_lat(base-3); maxLat=dec_lat(base); minLon=dec_lon(base-3); maxLon=dec_lon(base)
print('poly',minLat,maxLat,minLon,maxLon)
print('encode grid minLat ceil',enc_lat_ceil(minLat),'maxlat',enc_lat(maxLat),'minLonCeil',enc_lon_ceil(minLon),'maxLon',enc_lon(maxLon))
